styl:
.brad-full { border-radius: 32px !important; }
.w280 { width: 100%;
  max-width: 280px; }
@media screen and (max-width: 600px) {
  .w280 { max-width: 100% !important; }
}
.butt-link { font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px; }
.white-bg { background-color: #fff; }
.data { display: inline-block;
  padding: 6px 16px;
  background: #ffe6d5;
  border-radius: 12px;
  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 16px;
  line-height: 20px;
  color: #ff8516;
  text-align: left; }
@media screen and (max-width: 600px) {
  .data { font-size: 14px !important; }
}
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 24px !important;
    line-height: 32px !important; }
}
.small-title { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 24px;
  line-height: 31px;
  color: #393a44; }
@media screen and (max-width: 600px) {
  .small-title { font-size: 21px !important;
    line-height: 29px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb8 { padding-bottom: 8px; }
.pb24 { padding-bottom: 24px; }
.pb32 { padding-bottom: 32px; }
.pb44 { padding-bottom: 44px; }
.pt24 { padding-top: 24px; }
.pt44 { padding-top: 44px; }
.h-8 { font-size: 8px;
  line-height: 8px;
  height: 8px; }
.h-12 { font-size: 8px;
  line-height: 12px;
  height: 12px; }
.h-24 { font-size: 8px;
  line-height: 24px;
  height: 24px; }
.h-40 { font-size: 8px;
  line-height: 40px;
  height: 40px; }
.left-block { display: block !important;
  width: 52%;
  padding: 29px 0 29px 24px;
  vertical-align: top; }
.w100 { width: 100%; }
@media screen and (max-width: 600px) {
  .text.mob-text,
  .grey-text.mob-text { font-size: 17px !important; }
}
.w-a { width: auto !important;
  vertical-align: middle; }
.number { background: #ececed;
  width: 54px;
  max-height: 54px;
  border-radius: 16px;
  font-family: Helvetica !important;
  color: #393a44;
  font-weight: 700;
  font-size: 24px;
  line-height: 24px;
  padding: 15px 0;
  text-align: center; }
table[class=body] table.column td,
table[class=body] table.columns td.m-w { min-width: 70px !important;
  width: 70px !important; }
.orange-back-1 { background: #fff8f0 url("https://fsms.quadcode.com/storage/public/d6/26/tn0ggnfnh4cs78ng/rfm-331-top.png") center no-repeat;
  background-size: cover;
  border-radius: 24px; }
.orange-back-2 { background: #fff8f0 url("https://fsms.quadcode.com/storage/public/d6/26/tn0ggnfnh4cs78o0/rfm-331-middle.png") center no-repeat;
  background-size: cover;
  border-radius: 24px; }
.orange-back-3 { background: #fff8f0 url("https://fsms.quadcode.com/storage/public/d6/26/tn7vhhgea139ulg0/rfm-331-bottom.png") center no-repeat;
  background-size: cover;
  border-radius: 24px; }
.line-block { border: 1px solid #ececed;
  border-radius: 24px;
  padding: 24px; }
@media screen and (max-width: 600px) {
  .line-block { padding: 20px !important; }
}
